import { useEffect, useMemo, useRef, useState } from 'react';
import { ArrowLeft, ArrowRight, Check, CheckCircle2, FileUp, Plus, ShieldCheck, Trash2 } from 'lucide-react';
import { saveExternalClientIntakeSection, submitExternalClientIntake, uploadExternalClientIntakeDocument } from '../../lib/fiteatsyConsultantsApi';
import { choices, getTypicalMealSuggestions, intakeSections, labelFor, optionPairs, resolveNutritionCompatibility, sanitiseSection, toggleMulti, validateSection } from '../../lib/externalIntakeV2';
import { canonicalPhoneDisplay, normaliseWaterIntake, validatePdfFile, WATER_INTAKE_OPTIONS } from '../../lib/externalIntakeCorrections.mjs';

const blankMedication={name:'',dose:'',frequency:'',reason:'',startDate:''};
const message={lifestyle:"Great — next, let's understand your daily routine.",nutrition:'Almost there. A few questions about nutrition.',reportsDocuments:'Reports are optional. You can always share them later.'};
const safeExternalMessage=(error,fallback)=>error?.data?.safe_message||error?.data?.error?.safe_message||error?.data?.data?.safe_message||(error?.status&&error.status<500?error.message:fallback);
export const formatCanonicalDob=(value)=>{const match=typeof value==='string'&&value.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!match)return value?'Date needs review':'Not provided';const date=new Date(Date.UTC(Number(match[1]),Number(match[2])-1,Number(match[3])));if(Number.isNaN(date.getTime())||date.getUTCFullYear()!==Number(match[1])||date.getUTCMonth()!==Number(match[2])-1||date.getUTCDate()!==Number(match[3]))return'Date needs review';return date.toLocaleDateString(undefined,{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});};
export default function ExternalClientHealthIntake({token,initial,missingOnly=false,practiceName='Your consultant',onComplete}){
  if(!missingOnly)initial={...initial,missingRequiredFields:[]};
  const [answers,setAnswers]=useState(initial.sections||{});const [index,setIndex]=useState(0);const [completion,setCompletion]=useState(initial.completionPercent||0);const [saveState,setSaveState]=useState('saved');const [lastSaved,setLastSaved]=useState(initial.lastSavedAt||null);const [error,setError]=useState('');const [consent,setConsent]=useState(false);const [documents,setDocuments]=useState(initial.documents||[]);
  const [missingFields,setMissingFields]=useState(initial.missingRequiredFields||[]);const [missingValues,setMissingValues]=useState({});
  const [uploadState,setUploadState]=useState('idle');
  const applicable=useMemo(()=>intakeSections.filter(([name])=>name!=='womensHealth'||answers.aboutYou?.gender==='FEMALE'),[answers.aboutYou?.gender]);
  useEffect(()=>{const found=applicable.findIndex(([name])=>name===initial.currentSection);setIndex(found<0?0:found);},[]);
  const [key,title]=applicable[Math.min(index,applicable.length-1)];const data=answers[key]||{};
  const set=(field,value)=>setAnswers(current=>({...current,[key]:sanitiseSection(key,{...(current[key]||{}),[field]:value})}));
  const initialRender=useRef(true);useEffect(()=>{if(initialRender.current){initialRender.current=false;return;}if(['review','consent','reportsDocuments'].includes(key)||!Object.keys(data).length)return;setSaveState('saving');const timer=setTimeout(()=>saveExternalClientIntakeSection(token,key,sanitiseSection(key,data),key).then(result=>{setCompletion(result.intake.completionPercent);setLastSaved(result.intake.lastSavedAt||new Date().toISOString());setSaveState('saved');}).catch(()=>setSaveState('error')),700);return()=>clearTimeout(timer);},[token,key,data]);
  const go=async(next)=>{if(next<index){setError('');setIndex(Math.max(0,next));return;}if(!['review','consent','reportsDocuments'].includes(key)){const validation=validateSection(key,data);if(validation){setError(validation);return;}setSaveState('saving');try{const nextKey=applicable[Math.min(next,applicable.length-1)][0];const result=await saveExternalClientIntakeSection(token,key,sanitiseSection(key,data),nextKey);setCompletion(result.intake.completionPercent);setLastSaved(result.intake.lastSavedAt||new Date().toISOString());setSaveState('saved');}catch(requestError){setError(safeExternalMessage(requestError,'Unable to save this section.'));setSaveState('error');return;}}setError('');setIndex(Math.min(next,applicable.length-1));};
  const upload=async(event)=>{const file=event.target.files?.[0];if(!file)return;setSaveState('saving');setUploadState('validating');setError('');try{const validation=await validatePdfFile(file);if(validation)throw new Error(validation);const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());const idempotencyKey=`intake-report-${Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,'0')).join('')}`;setUploadState('uploading');const result=await uploadExternalClientIntakeDocument(token,'LAB_REPORT',file,idempotencyKey);setDocuments(current=>current.some(item=>item.id===result.document.id)?current:[...current,result.document]);setUploadState('success');setSaveState('saved');setLastSaved(new Date().toISOString());}catch(requestError){setError(safeExternalMessage(requestError,requestError.message||'The blood report could not be uploaded. Your invitation is still active; please retry.'));setUploadState('failed');setSaveState('error');}finally{event.target.value='';}};
  const submit=async()=>{if(!consent){setError('Please provide consent before submitting.');return;}setSaveState('saving');setError('');try{const result=await submitExternalClientIntake(token);onComplete(result.practiceName||practiceName);}catch(requestError){setError(safeExternalMessage(requestError,'Unable to submit your health profile.'));setSaveState('error');}};
  const saveMissing=async()=>{setSaveState('saving');setError('');try{let latest=null;for(const field of missingFields){const value=missingValues[field.code];if(value===undefined||value===null||value==='')throw new Error(`${field.label} is required.`);latest=await saveExternalClientIntakeSection(token,field.section,{...(answers[field.section]||{}),[field.field]:value},field.section);setAnswers(current=>({...current,[field.section]:{...(current[field.section]||{}),[field.field]:value}}));}const next=latest?.intake?.missingRequiredFields||[];setMissingFields(next);setCompletion(latest?.intake?.completionPercent??completion);setSaveState('saved');setLastSaved(latest?.intake?.lastSavedAt||new Date().toISOString());}catch(requestError){setError(safeExternalMessage(requestError,requestError.message||'Unable to save missing information.'));setSaveState('error');}};
  const progress=completion;
  if(initial.missingRequiredFields?.length){return <div className="min-h-[100dvh] bg-[#f6f7f8] px-3 py-6 text-slate-950"><main className="mx-auto max-w-2xl rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-8"><p className="text-sm font-semibold text-emerald-700">Continue Health Profile</p><h1 className="mt-1 text-2xl font-semibold">{missingFields.length?`${missingFields.length} required item${missingFields.length===1?'':'s'} remaining`:'Review and submit'}</h1><p className="mt-2 text-sm text-slate-500">Completed sections are skipped. Only information still required for your care plan is shown.</p>{missingFields.length?<div className="mt-7 space-y-7">{missingFields.filter(field=>field.clientCanEdit).map(field=><FocusedRequiredFieldControl key={field.code} field={field} value={missingValues[field.code]??''} onChange={value=>setMissingValues(current=>({...current,[field.code]:value}))}/>)}</div>:<div className="mt-7"><Consent checked={consent} onChange={setConsent}/></div>}{error&&<p role="alert" className="mt-5 rounded-xl bg-red-50 px-4 py-3 text-sm text-red-700">{error}</p>}<div className="mt-7 flex justify-end">{missingFields.length?<button disabled={saveState==='saving'} onClick={saveMissing} className="min-h-11 rounded-xl bg-slate-950 px-5 text-sm font-semibold text-white disabled:opacity-50">{saveState==='saving'?'Saving…':'Save & Recheck'}</button>:<button disabled={saveState==='saving'} onClick={submit} className="min-h-11 rounded-xl bg-emerald-700 px-5 text-sm font-semibold text-white disabled:opacity-50">Submit health profile</button>}</div></main></div>}
  return <div className="min-h-[100dvh] overflow-x-hidden bg-[#f6f7f8] text-slate-950"><div className="mx-auto max-w-3xl px-3 pb-28 pt-4 sm:px-6 sm:pb-32 sm:pt-8"><header className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5"><div className="flex items-center gap-3"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-slate-950 text-white"><ShieldCheck size={21}/></div><div className="min-w-0"><p className="text-[11px] font-semibold uppercase tracking-[.16em] text-slate-500">Secure health profile</p><h1 className="truncate text-base font-semibold sm:text-lg">{practiceName}</h1></div></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-slate-100" role="progressbar" aria-label="Health profile completion" aria-valuenow={progress} aria-valuemin="0" aria-valuemax="100"><div className="h-full rounded-full bg-emerald-600 transition-all" style={{width:`${progress}%`}}/></div><div className="mt-2 flex items-start justify-between gap-3 text-xs text-slate-500"><span>Step {index+1} of {applicable.length} · {title}</span><SaveStatus state={saveState} lastSaved={lastSaved}/></div></header><main className="mt-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:mt-5 sm:p-8"><p className="text-sm font-semibold text-emerald-700">{title}</p><h2 className="mt-1 text-2xl font-semibold tracking-tight">{headline(key)}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{message[key]||'You can skip anything you’re unsure about unless it is marked required.'}</p><div className="mt-6"><Section section={key} value={data} set={set} answers={answers} documents={documents} upload={upload} uploadState={uploadState} onEdit={section=>setIndex(applicable.findIndex(([name])=>name===section))} consent={consent} setConsent={setConsent}/></div>{error&&<p id="intake-error" role="alert" className="mt-5 rounded-xl bg-red-50 px-4 py-3 text-sm font-medium text-red-700">{error}</p>}</main><p className="mt-5 text-center text-xs leading-5 text-slate-500">Your answers are saved as you go and shared only with {practiceName}.</p></div><nav aria-label="Intake navigation" className="fixed inset-x-0 bottom-0 z-40 border-t border-slate-200 bg-white/95 px-3 py-3 shadow-[0_-8px_30px_rgba(15,23,42,.08)] backdrop-blur sm:px-6"><div className="mx-auto flex max-w-3xl items-center justify-between gap-3"><button type="button" disabled={index===0||saveState==='saving'} onClick={()=>go(index-1)} className="inline-flex min-h-11 items-center gap-2 rounded-xl px-4 text-sm font-semibold text-slate-600 focus:outline-none focus-visible:ring-2 focus-visible:ring-slate-900 disabled:opacity-30"><ArrowLeft size={18}/>Back</button>{key==='consent'?<button type="button" disabled={saveState==='saving'} onClick={submit} className="min-h-11 rounded-xl bg-emerald-700 px-5 text-sm font-semibold text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-700 focus-visible:ring-offset-2 disabled:opacity-50">{saveState==='saving'?'Submitting…':'Submit health profile'}</button>:<button type="button" disabled={saveState==='saving'} onClick={()=>go(index+1)} className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-slate-950 px-5 text-sm font-semibold text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-slate-950 focus-visible:ring-offset-2 disabled:opacity-50">Continue<ArrowRight size={18}/></button>}</div></nav></div>;
}
const headline=key=>({aboutYou:'Let’s start with you',medicalHistory:'Your medical background',conditionsSymptoms:'How are you feeling?',allergiesFamilyHistory:'Allergies and family history',medicationsSupplements:'Medicines and supplements',lifestyle:'Your daily routine',sleepStress:'Sleep and stress',activityHydration:'Movement and hydration',nutrition:'How you usually eat',goals:'What would you like to improve?',measurements:'Measurements you know',womensHealth:"Women’s health",reportsDocuments:'Have a recent report?',review:'Review your health profile',consent:'Consent and submit'}[key]||key);
function SaveStatus({state,lastSaved}){return <span role="status" className={state==='error'?'text-red-600':'text-slate-500'}>{state==='saving'?'Saving…':state==='error'?'Save failed':lastSaved?`Saved · ${new Date(lastSaved).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`:'Saved'}</span>}
function Section(props){const {section,value,set}=props;switch(section){
case 'aboutYou':return <Stack><ReadOnlyValue label="First name" value={value.firstName||'Not provided'}/><ReadOnlyValue label="Last name" value={value.lastName||'Not provided'}/>{value.dateOfBirth?<ReadOnlyValue label="Date of birth" value={formatCanonicalDob(value.dateOfBirth)}/>:<Text label="Date of birth" required type="date" value={value.dateOfBirth} onChange={v=>set('dateOfBirth',v)}/>}<Pills label="Gender" required single options={choices.gender} value={value.gender} onChange={v=>set('gender',v)}/><ReadOnlyValue label="Mobile number" value={canonicalPhoneDisplay(value.mobile)}/><ReadOnlyValue label="Email" value={value.email||'Not provided'}/><Pills label="Occupation activity type" single options={choices.occupationActivity} value={value.occupationActivity} onChange={v=>set('occupationActivity',v)}/>{value.occupationActivity==='OTHER'&&<Text label="Occupation" value={value.occupation} onChange={v=>set('occupation',v)}/>}<div className="grid gap-4 sm:grid-cols-3"><Text label="Country" value={value.locationCountry} onChange={v=>set('locationCountry',v)}/><Text label="State / Region" value={value.locationRegion} onChange={v=>set('locationRegion',v)}/><Text label="City" value={value.locationCity} onChange={v=>set('locationCity',v)}/></div>{value.location&&!value.locationCountry&&<ReadOnlyValue label="Previous location" value={value.location}/>}</Stack>;
case 'medicalHistory':return <Stack><YesNo label="Have you had surgery?" value={value.hadSurgery} onChange={v=>set('hadSurgery',v)}/>{value.hadSurgery==='YES'&&<Text label="Procedure" required value={value.surgeryProcedure} onChange={v=>set('surgeryProcedure',v)}/>}<YesNo label="Have you been hospitalised?" value={value.hospitalised} onChange={v=>set('hospitalised',v)}/>{value.hospitalised==='YES'&&<Text label="Reason" required value={value.hospitalisationReason} onChange={v=>set('hospitalisationReason',v)}/>}<YesNo label="Currently under medical treatment?" value={value.underTreatment} onChange={v=>set('underTreatment',v)}/>{value.underTreatment==='YES'&&<TreatmentSheet value={value} set={set}/>}</Stack>;
case 'conditionsSymptoms':return <Stack><Pills label="Medical conditions" options={choices.conditions} value={value.conditions} onChange={v=>set('conditions',v)}/><Pills label="Current symptoms" options={choices.symptoms} value={value.symptoms} onChange={v=>set('symptoms',v)}/>{value.symptoms?.length>0&&!value.symptoms.includes('NO_CURRENT_SYMPTOMS')&&<Pills label="How often? (optional)" single options={['RARELY','SOMETIMES','OFTEN','DAILY']} value={value.symptomFrequency} onChange={v=>set('symptomFrequency',v)}/>}</Stack>;
case 'allergiesFamilyHistory':return <Stack><Pills label="Known allergies?" single options={['YES','NO','NOT_SURE']} value={value.hasAllergies} onChange={v=>set('hasAllergies',v)}/>{value.hasAllergies==='YES'&&<><Pills label="Allergy type" required options={['FOOD','MEDICATION','ENVIRONMENTAL','OTHER']} value={value.allergyTypes} onChange={v=>set('allergyTypes',v)}/>{value.allergyTypes?.includes('FOOD')&&<Pills label="Food allergies" options={['MILK_DAIRY','PEANUTS','TREE_NUTS','EGG','WHEAT','SOY','FISH','SHELLFISH','OTHER']} value={value.foodAllergies} onChange={v=>set('foodAllergies',v)}/>}<Text label="Reaction or other details (optional)" area value={value.allergyNotes} onChange={v=>set('allergyNotes',v)}/></>}<Pills label="Family history" options={choices.familyHistory} value={value.familyHistory} onChange={v=>set('familyHistory',v)}/></Stack>;
case 'medicationsSupplements':return <Stack><YesNo label="Taking prescribed medicines?" value={value.takesMedication} onChange={v=>set('takesMedication',v)}/>{value.takesMedication==='YES'&&<Repeatable title="Medicine" rows={value.medications} onChange={v=>set('medications',v)} required/>}<YesNo label="Taking supplements?" value={value.takesSupplements} onChange={v=>set('takesSupplements',v)}/>{value.takesSupplements==='YES'&&<><Pills label="Supplements" options={choices.supplementTypes} value={value.supplementTypes} onChange={v=>set('supplementTypes',v)}/><Text label="Dose or frequency (optional)" value={value.supplementNotes} onChange={v=>set('supplementNotes',v)}/></>}</Stack>;
case 'lifestyle':return <Stack><Pills label="Tobacco" single options={choices.tobacco} value={value.tobacco} onChange={v=>set('tobacco',v)}/><Pills label="Alcohol" single options={choices.alcohol} value={value.alcohol} onChange={v=>set('alcohol',v)}/><Pills label="Caffeinated drinks per day" single options={choices.caffeineCount} value={value.caffeineCount} onChange={v=>set('caffeineCount',v)}/>{value.caffeineCount&&value.caffeineCount!=='NONE'&&<Pills label="Caffeine type" options={choices.caffeineTypes} value={value.caffeineTypes} onChange={v=>set('caffeineTypes',v)}/>}<Text label="Work schedule (optional)" value={value.workSchedule} onChange={v=>set('workSchedule',v)}/></Stack>;
case 'sleepStress':return <Stack><Pills label="Sleep duration" single options={choices.sleepDuration} value={value.sleepDuration} onChange={v=>set('sleepDuration',v)}/><Pills label="Sleep quality" single options={choices.sleepQuality} value={value.sleepQuality} onChange={v=>set('sleepQuality',v)}/><Pills label="Sleep concerns" options={choices.sleepConcerns} value={value.sleepConcerns} onChange={v=>set('sleepConcerns',v)}/><div className="grid gap-4 sm:grid-cols-2"><Text label="Usual bedtime" type="time" value={value.bedtime} onChange={v=>set('bedtime',v)}/><Text label="Usual wake time" type="time" value={value.wakeTime} onChange={v=>set('wakeTime',v)}/></div><Pills label="Stress level" single options={choices.stressLevel} value={value.stressLevel} onChange={v=>set('stressLevel',v)}/><Pills label="Sources of stress" options={choices.stressSources} value={value.stressSources} onChange={v=>set('stressSources',v)}/></Stack>;
case 'activityHydration':return <Stack><Pills label="Daily activity" single options={choices.activityLevel} value={value.activityLevel} onChange={v=>set('activityLevel',v)}/><YesNo label="Intentional exercise?" value={value.intentionalExercise} onChange={v=>set('intentionalExercise',v)}/>{value.intentionalExercise==='YES'&&<><Pills label="Exercise type" options={choices.exerciseTypes} value={value.exerciseTypes} onChange={v=>set('exerciseTypes',v)}/><Pills label="Frequency" single options={choices.exerciseFrequency} value={value.exerciseFrequency} onChange={v=>set('exerciseFrequency',v)}/></>}<Pills label="Water intake" single options={WATER_INTAKE_OPTIONS} value={normaliseWaterIntake(value)} onChange={v=>set('waterIntakeMl',Number(v))}/>{!value.waterIntakeMl&&value.waterIntake&&<ReadOnlyValue label="Previously recorded water range" value={labelFor(value.waterIntake)}/>}</Stack>;
case 'nutrition':return <NutritionFields value={value} set={set} answers={props.answers}/>;
case 'goals':return <Stack><Pills label="Select your goals" required options={choices.goals} value={value.goals} onChange={v=>set('goals',v)}/>{value.goals?.length>0&&<Pills label="Main priority" required single options={value.goals} value={value.primaryGoal} onChange={v=>set('primaryGoal',v)}/>}<Text label="Anything else you want your consultant to know? (optional)" area value={value.goalNotes} onChange={v=>set('goalNotes',v)}/></Stack>;
case 'measurements':return <div className="grid gap-4 sm:grid-cols-2"><Text label="Height (cm)" type="number" inputMode="decimal" value={value.heightCm} onChange={v=>set('heightCm',v)}/><Text label="Weight (kg)" type="number" inputMode="decimal" value={value.weightKg} onChange={v=>set('weightKg',v)}/><Text label="Waist (cm)" type="number" inputMode="decimal" value={value.waistCm} onChange={v=>set('waistCm',v)}/><Text label="Hip (cm)" type="number" inputMode="decimal" value={value.hipCm} onChange={v=>set('hipCm',v)}/><Text label="Blood pressure" inputMode="numeric" value={value.bloodPressure} onChange={v=>set('bloodPressure',v)}/><Text label="Resting heart rate (bpm)" type="number" inputMode="numeric" value={value.restingHeartRate} onChange={v=>set('restingHeartRate',v)}/><Text label="Glucose" inputMode="decimal" value={value.glucose} onChange={v=>set('glucose',v)}/><Text label="Glucose unit" value={value.glucoseUnit} onChange={v=>set('glucoseUnit',v)}/></div>;
case 'womensHealth':return <Stack><Pills label="Menstrual status" single options={choices.menstrualStatus} value={value.menstrualStatus} onChange={v=>set('menstrualStatus',v)}/>{['REGULAR_PERIODS','IRREGULAR_PERIODS'].includes(value.menstrualStatus)&&<><Pills label="Cycle length" single options={choices.cycleLength} value={value.cycleLength} onChange={v=>set('cycleLength',v)}/><Pills label="Period symptoms" options={choices.periodSymptoms} value={value.periodSymptoms} onChange={v=>set('periodSymptoms',v)}/><Text label="Last period (optional)" type="date" value={value.lastPeriod} onChange={v=>set('lastPeriod',v)}/></>}</Stack>;
case 'reportsDocuments':return <DocumentSection documents={props.documents} upload={props.upload} uploadState={props.uploadState}/>;case 'review':return <Review answers={props.answers} onEdit={props.onEdit}/>;case 'consent':return <Consent checked={props.consent} onChange={props.setConsent}/>;default:return null;}}
function ReadOnlyValue({label,value}){return <div className="rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">{label}</p><p className="mt-1 font-semibold text-slate-900">{value}</p><p className="mt-1 text-xs text-slate-500">Provided by your consultant</p></div>}
function TreatmentSheet({value,set}){const [open,setOpen]=useState(!(value.treatments?.length));return <><button type="button" onClick={()=>setOpen(true)} className="flex min-h-12 w-full items-center justify-between rounded-xl border border-slate-300 px-4 text-left text-sm font-semibold"><span>{value.treatments?.length?`${value.treatments.length} treatment${value.treatments.length===1?'':'s'} selected`:'Choose treatment details'}</span><ArrowRight size={17}/></button>{open&&<div className="fixed inset-0 z-50 flex items-end bg-slate-950/45 sm:items-center sm:justify-center" role="dialog" aria-modal="true" aria-labelledby="treatment-title"><div className="max-h-[88dvh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl sm:max-w-2xl sm:rounded-3xl sm:p-7"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold uppercase tracking-wider text-emerald-700">Treatment details</p><h3 id="treatment-title" className="mt-1 text-xl font-semibold">What treatment are you currently receiving?</h3></div><button type="button" aria-label="Close treatment details" onClick={()=>setOpen(false)} className="grid h-11 w-11 place-items-center rounded-full bg-slate-100"><Trash2 className="rotate-45" size={18}/></button></div><div className="mt-6"><Pills label="Select all that apply" options={choices.treatments} value={value.treatments} onChange={v=>set('treatments',v)}/></div>{value.treatments?.includes('OTHER')&&<div className="mt-5"><Text label="Please specify treatment" required value={value.otherTreatment} onChange={v=>set('otherTreatment',v)}/></div>}<div className="mt-5"><Text label="Add a note (optional)" area value={value.treatmentNote} onChange={v=>set('treatmentNote',v)}/></div><button type="button" onClick={()=>setOpen(false)} className="mt-6 min-h-12 w-full rounded-xl bg-slate-950 px-5 font-semibold text-white">Done</button></div></div>}</>}
function NutritionFields({value,set,answers}){const compatibility=resolveNutritionCompatibility(value.dietPreference,value.restrictions);const location=answers.aboutYou?.location||'';const mealProps={location,dietPreference:value.dietPreference,restrictions:value.restrictions||[],allergies:answers.allergiesFamilyHistory?.foodAllergies||[],intolerances:value.intolerances||[]};return <Stack><Pills label="Primary diet" single options={choices.dietPreference} value={value.dietPreference} onChange={v=>set('dietPreference',v)}/><Pills label="Cultural or religious restrictions" options={choices.restrictions} value={value.restrictions} onChange={v=>set('restrictions',v)}/>{compatibility.conflict&&<div role="alert" className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-950"><p className="font-semibold">Jain food preference is generally vegetarian. Would you like to change your primary diet to Vegetarian?</p><div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={()=>set('dietPreference','VEGETARIAN')} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white">Change to Vegetarian</button><button type="button" onClick={()=>set('restrictions',(value.restrictions||[]).filter(item=>item!=='JAIN'))} className="min-h-11 rounded-xl border border-slate-300 px-4 font-semibold">Remove Jain</button></div></div>}<Pills label="Food discomfort or intolerance" options={choices.intolerances} value={value.intolerances} onChange={v=>set('intolerances',v)}/><Pills label="Meals per day" single options={choices.mealsPerDay} value={value.mealsPerDay} onChange={v=>set('mealsPerDay',v)}/><Pills label="Do you skip meals?" single options={choices.skipMeals} value={value.skipMeals} onChange={v=>set('skipMeals',v)}/>{['SOMETIMES','OFTEN'].includes(value.skipMeals)&&<Pills label="Which meals?" options={choices.skippedMeals} value={value.skippedMeals} onChange={v=>set('skippedMeals',v)}/>}<Pills label="Eating out" single options={choices.eatingOut} value={value.eatingOut} onChange={v=>set('eatingOut',v)}/><YesNo label="Cravings?" value={value.hasCravings} onChange={v=>set('hasCravings',v)}/>{value.hasCravings==='YES'&&<Pills label="Cravings" options={choices.cravings} value={value.cravings} onChange={v=>set('cravings',v)}/>}<MealSelector label="Typical breakfast" field="breakfast" meal="breakfast" value={value.breakfast} set={set} context={mealProps}/><MealSelector label="Typical lunch" field="lunch" meal="lunch" value={value.lunch} set={set} context={mealProps}/><MealSelector label="Typical dinner" field="dinner" meal="dinner" value={value.dinner} set={set} context={mealProps}/><MealSelector label="Typical snacks" field="snacks" meal="snacks" value={value.snacks} set={set} context={mealProps}/></Stack>}
function MealSelector({label,field,meal,value,set,context}){const selected=Array.isArray(value)?value:(value?[value]:[]);const [custom,setCustom]=useState('');const suggestions=getTypicalMealSuggestions({meal,...context});const toggle=name=>set(field,selected.includes(name)?selected.filter(item=>item!==name):[...selected,name]);const add=()=>{const next=custom.trim();if(next&&!selected.includes(next))set(field,[...selected,next]);setCustom('');};return <fieldset><legend className="text-sm font-semibold text-slate-800">{label} <span className="font-normal text-slate-500">(optional)</span></legend>{context.location&&<p className="mt-1 text-xs text-slate-500">Suggestions tailored to {context.location}</p>}<div className="mt-3 flex flex-wrap gap-2">{suggestions.map(name=><button key={name} type="button" role="checkbox" aria-checked={selected.includes(name)} onClick={()=>toggle(name)} className={`min-h-11 rounded-full border px-4 py-2 text-sm font-semibold ${selected.includes(name)?'border-emerald-700 bg-emerald-700 text-white':'border-slate-300 bg-white text-slate-700'}`}>{selected.includes(name)&&<Check size={15} className="mr-1 inline"/>}{name}</button>)}</div><div className="mt-3 flex gap-2"><input aria-label={`Add another ${label.toLowerCase()} food`} value={custom} onChange={event=>setCustom(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();add();}}} placeholder="Search or add your own" className="min-h-11 flex-1 rounded-xl border border-slate-300 px-3.5"/><button type="button" onClick={add} className="min-h-11 rounded-xl border border-slate-300 px-4 font-semibold">Add</button></div>{selected.filter(name=>!suggestions.includes(name)).length>0&&<p className="mt-2 text-xs text-slate-500">Saved custom or legacy choices: {selected.filter(name=>!suggestions.includes(name)).join(', ')}</p>}</fieldset>}
function Stack({children}){return <div className="space-y-7">{children}</div>}
function Text({label,required=false,area=false,value='',onChange,type='text',inputMode}){const id=`field-${label.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;const classes="min-h-11 w-full rounded-xl border border-slate-300 bg-white px-3.5 py-3 text-base outline-none transition focus:border-slate-950 focus:ring-2 focus:ring-slate-950/10";return <label htmlFor={id} className="block text-sm font-semibold text-slate-700"><span>{label}{required&&<span aria-hidden="true"> *</span>}</span>{area?<textarea id={id} rows={3} value={value||''} onChange={event=>onChange(event.target.value)} className={`mt-2 ${classes}`}/>:<input id={id} required={required} type={type} inputMode={inputMode} min={type==='number'?'0':undefined} value={value||''} onChange={event=>onChange(event.target.value)} className={`mt-2 ${classes}`}/>}</label>}
function Pills({label,options,value,onChange,single=false,required=false}){const selected=single?(value?[value]:[]):(Array.isArray(value)?value:[]);return <fieldset><legend className="text-sm font-semibold text-slate-800">{label}{required&&<span aria-hidden="true"> *</span>}</legend><div className="mt-3 flex flex-wrap gap-2">{optionPairs(options).map(([code,text])=>{const active=selected.includes(code);return <button key={code} type="button" role={single?'radio':'checkbox'} aria-checked={active} onClick={()=>onChange(single?(active?'':code):toggleMulti(selected,code))} className={`inline-flex min-h-11 items-center gap-2 rounded-full border px-4 py-2.5 text-sm font-semibold transition focus:outline-none focus-visible:ring-2 focus-visible:ring-slate-950 focus-visible:ring-offset-2 ${active?'border-emerald-700 bg-emerald-700 text-white':'border-slate-300 bg-white text-slate-700 hover:border-slate-500'}`}>{active&&<Check size={16} aria-hidden="true"/>}{text}</button>})}</div></fieldset>}
function YesNo(props){return <Pills {...props} single options={['YES','NO']}/>}
export function FocusedRequiredFieldControl({field,value,onChange}){if(field.code==='PRIMARY_GOAL')return <Pills label={field.label} required single options={choices.goals} value={value} onChange={onChange}/>;if(field.code==='DIET_PREFERENCE')return <Pills label={field.label} required single options={choices.dietPreference} value={value} onChange={onChange}/>;if(field.code==='CURRENT_WEIGHT')return <Text label={`${field.label} (${field.unit||'kg'})`} required type="number" inputMode="decimal" value={value} onChange={onChange}/>;return null;}
function Repeatable({title,rows=[],onChange,required}){const list=rows.length?rows:[blankMedication];const update=(index,field,value)=>onChange(list.map((row,rowIndex)=>rowIndex===index?{...row,[field]:value}:row));return <section><div className="flex items-center justify-between"><h3 className="text-sm font-semibold text-slate-800">{title}s</h3><button type="button" onClick={()=>onChange([...list,{...blankMedication}])} className="inline-flex min-h-11 items-center gap-1 rounded-xl px-3 text-sm font-semibold text-emerald-700"><Plus size={17}/>Add</button></div><div className="space-y-3">{list.map((row,index)=><div key={index} className="relative grid gap-3 rounded-2xl border border-slate-200 bg-slate-50 p-4 sm:grid-cols-2"><Text label={`${title} name`} required={required} value={row.name} onChange={v=>update(index,'name',v)}/><Text label="Dose" value={row.dose} onChange={v=>update(index,'dose',v)}/><Pills label="Frequency" single options={choices.medicationFrequency} value={row.frequency} onChange={v=>update(index,'frequency',v)}/><Text label="Start date" type="date" value={row.startDate} onChange={v=>update(index,'startDate',v)}/><div className="sm:col-span-2"><Text label="Reason (optional)" value={row.reason} onChange={v=>update(index,'reason',v)}/></div>{list.length>1&&<button type="button" aria-label={`Remove ${title.toLowerCase()} ${index+1}`} onClick={()=>onChange(list.filter((_,rowIndex)=>rowIndex!==index))} className="absolute right-2 top-2 grid h-11 w-11 place-items-center rounded-full text-red-600 hover:bg-red-50"><Trash2 size={17}/></button>}</div>)}</div></section>}
function DocumentSection({documents,upload,uploadState}){const [open,setOpen]=useState(false);return <Stack><p className="rounded-xl bg-blue-50 px-4 py-3 text-sm leading-6 text-blue-800">Optional — you can continue without a blood report. Existing uploaded PDFs remain available when you return.</p><button type="button" onClick={()=>setOpen(true)} className="inline-flex min-h-14 items-center justify-center gap-2 rounded-xl border-2 border-dashed border-slate-300 p-5 text-sm font-semibold text-slate-700"><FileUp size={20}/>Upload blood-report PDF</button>{open&&<div className="fixed inset-0 z-50 flex items-end bg-slate-950/45 sm:items-center sm:justify-center" role="dialog" aria-modal="true" aria-labelledby="report-upload-title"><div className="w-full rounded-t-3xl bg-white p-5 shadow-2xl sm:max-w-lg sm:rounded-3xl sm:p-7"><h3 id="report-upload-title" className="text-xl font-semibold">Upload blood report</h3><p className="mt-2 text-sm text-slate-500">PDF only · maximum 12 MB. The file is linked only to this intake and client.</p><label className="mt-5 flex min-h-16 cursor-pointer items-center justify-center gap-2 rounded-xl border-2 border-dashed border-slate-300 p-5 text-sm font-semibold"><FileUp size={20}/>{uploadState==='uploading'?'Uploading…':'Choose PDF'}<input aria-label="Choose blood-report PDF" type="file" accept="application/pdf,.pdf" disabled={uploadState==='uploading'} onChange={upload} className="sr-only"/></label><p role="status" className="mt-3 text-sm text-slate-600">{uploadState==='validating'?'Validating PDF…':uploadState==='success'?'Upload complete.':uploadState==='failed'?'Upload failed. Choose the PDF again to retry.':''}</p><button type="button" onClick={()=>setOpen(false)} className="mt-5 min-h-11 w-full rounded-xl bg-slate-950 px-4 font-semibold text-white">Done</button></div></div>}<div className="space-y-2">{documents.map(document=><div key={document.id} className="flex items-start gap-2 rounded-lg bg-slate-50 px-3 py-2 text-sm"><CheckCircle2 size={16} className="mt-0.5 shrink-0 text-emerald-600"/><span><strong className="block font-semibold">{document.fileName}</strong><span className="text-xs text-slate-500">{documentStatus(document.processingStatus)}</span></span></div>)}</div></Stack>}
function documentStatus(status){if(['UPLOADED','PROCESSING'].includes(status))return 'Report uploaded successfully. Secure processing is in progress.';if(['EXTRACTED','REVIEW_REQUIRED','CONFIRMED'].includes(status))return 'Processing complete. Your Consultant can review the results.';if(status==='FAILED')return 'The report is saved, but automated processing could not complete. Your invitation remains valid.';return 'Uploaded successfully.';}
function Review({answers,onEdit}){return <div className="space-y-3">{intakeSections.filter(([key])=>!['review','consent','reportsDocuments'].includes(key)).map(([key,title])=>{const entries=Object.entries(answers[key]||{}).filter(([,value])=>value!==''&&value!==null&&value!==undefined);return <section key={key} className="rounded-xl border border-slate-200 p-4"><div className="flex items-center justify-between"><h3 className="font-semibold">{title}</h3><button type="button" onClick={()=>onEdit(key)} className="min-h-11 rounded-lg px-3 text-sm font-semibold text-emerald-700">Edit</button></div>{entries.length?<dl className="mt-3 grid gap-2 text-sm sm:grid-cols-2">{entries.map(([name,value])=><div key={name}><dt className="text-slate-500">{labelFor(name)}</dt><dd className="break-words font-medium">{Array.isArray(value)?value.map(item=>typeof item==='object'?item.name:labelFor(item)).filter(Boolean).join(', '):labelFor(value)}</dd></div>)}</dl>:<p className="mt-2 text-sm text-slate-500">Skipped</p>}</section>})}</div>}
function Consent({checked,onChange}){return <div className="rounded-xl bg-slate-50 p-5"><label className="flex min-h-11 items-start gap-3"><input type="checkbox" checked={checked} onChange={event=>onChange(event.target.checked)} className="mt-1 h-5 w-5 rounded border-slate-400"/><span className="text-sm leading-6 text-slate-700">I consent to securely share my submitted health information and documents with this Consultant or practice for consultation and care purposes. This does not include marketing consent.</span></label></div>}
